import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"What to do when the dashboard runs but misbehaves?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/en/04.fehlerbehebung/02.dashboard-bedienung.md"},"headers":[],"relativePath":"adapter/esphome/fehlerbehebung/dashboard-bedienung.md","filePath":"adapter/esphome/fehlerbehebung/dashboard-bedienung.md","lastUpdated":null}'),h={name:"adapter/esphome/fehlerbehebung/dashboard-bedienung.md"};function s(d,e,i,n,b,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="what-to-do-when-the-dashboard-runs-but-misbehaves" tabindex="-1">What to do when the dashboard runs but misbehaves? <a class="header-anchor" href="#what-to-do-when-the-dashboard-runs-but-misbehaves" aria-label="Permalink to &quot;What to do when the dashboard runs but misbehaves?&quot;">​</a></h1><p><a id="ota-update-abort-time-out"></a></p><h2 id="why-does-the-ota-update-abort-or-time-out" tabindex="-1">Why does the OTA update abort or time out? <a class="header-anchor" href="#why-does-the-ota-update-abort-or-time-out" aria-label="Permalink to &quot;Why does the OTA update abort or time out?&quot;">​</a></h2><p>The OTA update runs between dashboard and device, the adapter is not involved.</p><p>A timeout right after a complete upload is normal. The device restarts with the new firmware and is briefly unreachable, then the adapter connects again.</p><p>If the upload stops in the middle, it is almost always the network or the device:</p><ol><li>Check the Wi-Fi signal of the device. Below about -80 dBm uploads often fail.</li><li>Check whether a firewall between the ioBroker host and the device blocks the OTA port.</li><li>If that does not help, flash once by cable.</li></ol><p><strong>See also:</strong> <a href="./../erste-schritte/dashboard-einschalten#flash-device-first-time-if">Flash by cable</a></p><p><a id="dashboard-ui-broken-browser"></a></p><h2 id="why-is-the-dashboard-ui-broken-in-the-browser" tabindex="-1">Why is the dashboard UI broken in the browser? <a class="header-anchor" href="#why-is-the-dashboard-ui-broken-in-the-browser" aria-label="Permalink to &quot;Why is the dashboard UI broken in the browser?&quot;">​</a></h2><p>The tab &quot;ESPHome&quot; only embeds the dashboard, the interface itself comes from ESPHome. Display errors in the editor or the log window are therefore usually caused by the dashboard or the browser.</p><ol><li>Open the dashboard directly in a browser tab of its own at <code>http://&lt;ioBroker IP&gt;:6052</code>.</li><li>Clear the browser cache or reload the page with Ctrl+F5.</li><li>Try another browser.</li></ol><p>If the error also shows directly in the browser, it is in the dashboard. Another ESPHome version may help then.</p><p><strong>See also:</strong> <a href="./../anleitungen/dashboard-nutzen#choose-update-esphome-dashboard-version">Choose the dashboard version</a></p>',14)])])}const c=a(h,[["render",s]]);export{u as __pageData,c as default};
